
(()=>{
'use strict';
const DATA = {"ORDER":[{"id":"foot","en":"At the foot of the altar","fr":"Au bas de l’autel","steps":[["sign-cross","Sign of the Cross · Introibo","Signe de croix · Introibo"],["judica","Psalm 42 · Judica me","Psaume 42 · Judica me"],["adjutorium","Adjutorium nostrum","Adjutorium nostrum"],["priest-confiteor","Confiteor of the priest","Confiteor du prêtre"],["ministers-confiteor","Confiteor of the ministers","Confiteor des ministres"],["ascend","The priest ascends the altar","Le prêtre monte à l’autel"],["oramus-te","Prayer and kiss of the altar","Prière et baiser de l’autel"]]},{"id":"entrance","en":"Entrance and praise","fr":"Entrée et louange","steps":[["incense-entrance","Incensation of the altar","Encensement de l’autel"],["introit","Introit","Introït"],["kyrie","Kyrie eleison","Kyrie eleison"],["gloria","Gloria in excelsis","Gloria in excelsis"],["collect","Collect","Collecte"]]},{"id":"word","en":"Readings and profession of faith","fr":"Lectures et profession de foi","steps":[["epistle","Epistle or Lesson","Épître ou Leçon"],["gradual","Gradual","Graduel"],["alleluia","Alleluia / Tract","Alléluia / Trait"],["gospel-prep","Preparation for the Gospel","Préparation à l’Évangile"],["gospel","Holy Gospel","Saint Évangile"],["credo","Nicene Creed","Credo"]]},{"id":"offertory","en":"Offertory","fr":"Offertoire","steps":[["offertory","Offertory antiphon","Antienne d’Offertoire"],["offer-host","Offering of the host","Offrande de l’hostie"],["water-wine","Water and wine","Eau et vin"],["offer-chalice","Offering of the chalice","Offrande du calice"],["in-spiritu","In spiritu humilitatis","In spiritu humilitatis"],["veni-sanctificator","Veni, Sanctificator","Veni, Sanctificator"],["incense-off","Incensation at the Offertory","Encensement à l’Offertoire"],["lavabo","Lavabo","Lavabo"],["suscipe-trinitas","Suscipe, sancta Trinitas","Suscipe, sancta Trinitas"],["orate-fratres","Orate, fratres","Orate, fratres"],["secret","Secret","Secrète"]]},{"id":"canon","en":"Preface and Roman Canon","fr":"Préface et Canon romain","steps":[["preface","Preface","Préface"],["sanctus","Sanctus","Sanctus"],["te-igitur","Te igitur","Te igitur"],["memento-living","Memento of the living","Mémento des vivants"],["communicantes","Communicantes","Communicantes"],["hanc","Hanc igitur","Hanc igitur"],["quam-oblationem","Quam oblationem","Quam oblationem"],["consecration-host","Consecration of the Host","Consécration de l’Hostie"],["consecration-chalice","Consecration of the Chalice","Consécration du Calice"],["unde-et-memores","Unde et memores","Unde et memores"],["supra-quae","Supra quae","Supra quae"],["supplices","Supplices te rogamus","Supplices te rogamus"],["memento-dead","Memento of the dead","Mémento des défunts"],["nobis-quoque","Nobis quoque peccatoribus","Nobis quoque peccatoribus"],["canon-doxology","Doxology of the Canon","Doxologie du Canon"]]},{"id":"communion","en":"Communion","fr":"Communion","steps":[["pater","Pater noster","Pater noster"],["libera-nos","Libera nos","Libera nos"],["fraction-pax","Fraction · Pax Domini","Fraction · Pax Domini"],["commingling","Commingling","Commixtion"],["agnus","Agnus Dei","Agnus Dei"],["peace-prayer","Prayer for peace","Prière pour la paix"],["communion-prep-fili","First prayer before Communion","Première prière avant la Communion"],["communion-prep-perceptio","Second prayer before Communion","Deuxième prière avant la Communion"],["priest-communion","Communion of the priest","Communion du prêtre"],["second-confiteor","Second Confiteor (where used)","Second Confiteor (là où il est employé)"],["ecce","Ecce Agnus Dei","Ecce Agnus Dei"],["domine-non-sum-dignus","Domine, non sum dignus","Domine, non sum dignus"],["communion-faithful","Communion of the faithful","Communion des fidèles"],["ablutions","Ablutions","Ablutions"],["communion-proper","Communion antiphon","Antienne de Communion"],["postcommunion","Postcommunion","Postcommunion"]]},{"id":"end","en":"Conclusion","fr":"Conclusion","steps":[["super-populum","Prayer over the People","Oraison sur le peuple"],["dismissal","Dismissal","Renvoi"],["placeat","Placeat tibi","Placeat tibi"],["blessing","Final blessing","Bénédiction finale"],["last-gospel","Last Gospel","Dernier Évangile"]]},{"id":"exceptional","en":"Exceptional rites","fr":"Rites exceptionnels","steps":[["candlemas-blessing","Candlemas · blessing of candles","Chandeleur · bénédiction des cierges"],["ashes-antiphon","Ash Wednesday · blessing of ashes","Mercredi des Cendres · bénédiction des cendres"],["palms-blessing","Palm Sunday · blessing of palms","Dimanche des Rameaux · bénédiction des rameaux"],["gf-prostration","Good Friday · opening prostration","Vendredi saint · prostration d’ouverture"],["gf-cross-unveiling","Good Friday · unveiling of the Cross","Vendredi saint · dévoilement de la Croix"],["vigil-fire","Easter Vigil · new fire","Vigile pascale · feu nouveau"],["vigil-exsultet","Easter Vigil · Exsultet","Vigile pascale · Exsultet"]]}],"EXTRA_SOURCES":{"trent22":{"label":"Council of Trent · Session XXII (1562)","label_fr":"Concile de Trente · Session XXII (1562)","kind":"Ecumenical council","kind_fr":"Concile œcuménique","url":"https://www.papalencyclicals.net/councils/trent/twenty-second-session.htm","note":"Doctrinal teaching on the Sacrifice of the Mass, ceremonies, the mixed chalice, liturgical language and pastoral explanation.","note_fr":"Enseignement doctrinal sur le Sacrifice de la Messe, les cérémonies, le calice mêlé, la langue liturgique et l’explication pastorale."},"music1958":{"label":"Sacred Congregation of Rites · De musica sacra et sacra liturgia (1958)","label_fr":"Sacrée Congrégation des Rites · De musica sacra et sacra liturgia (1958)","kind":"Authoritative instruction","kind_fr":"Instruction faisant autorité","url":"https://adoremus.org/1958/09/instruction-on-sacred-music/","note":"Period guidance on Latin, Gregorian chant, sung and low Mass, and degrees of congregational participation.","note_fr":"Normes de l’époque sur le latin, le chant grégorien, la Messe chantée et basse, et les degrés de participation des fidèles."},"rubricarum1960":{"label":"John XXIII · Rubricarum instructum (1960)","label_fr":"Jean XXIII · Rubricarum instructum (1960)","kind":"Motu proprio","kind_fr":"Motu proprio","url":"https://www.vatican.va/content/john-xxiii/la/motu_proprio/documents/hf_j-xxiii_motu-proprio_19600725_rubricarum-instructum.html","note":"Promulgates the revised code of rubrics immediately preceding the 1962 Missal and describes the history of accumulated rubrical revisions.","note_fr":"Promulgue le code révisé des rubriques qui précède immédiatement le Missel de 1962 et évoque l’histoire des révisions rubricales accumulées."},"piusX1903":{"label":"Pius X · Tra le sollecitudini (1903)","label_fr":"Pie X · Tra le sollecitudini (1903)","kind":"Motu proprio on sacred music","kind_fr":"Motu proprio sur la musique sacrée","url":"https://www.vatican.va/content/pius-x/la/motu_proprio/documents/hf_p-x_motu-proprio_19031122_sollecitudini.html","note":"Identifies Gregorian chant as the chant proper to the Roman Church and sets principles for sacred music.","note_fr":"Présente le chant grégorien comme le chant propre de l’Église romaine et fixe des principes pour la musique sacrée."},"musicae1955":{"label":"Pius XII · Musicae sacrae disciplina (1955)","label_fr":"Pie XII · Musicae sacrae disciplina (1955)","kind":"Encyclical on sacred music","kind_fr":"Encyclique sur la musique sacrée","url":"https://www.vatican.va/content/pius-xii/en/encyclicals/documents/hf_p-xii_enc_25121955_musicae-sacrae.html","note":"Authoritative teaching on sacred music and the Gregorian patrimony shortly before the 1962 Missal.","note_fr":"Enseignement faisant autorité sur la musique sacrée et le patrimoine grégorien peu avant le Missel de 1962."}},"TOPICS":[{"id":"orientation","title":"Why ad orientem?","title_fr":"Pourquoi ad orientem ?","summary":"Common liturgical orientation is about the direction of worship, not the priest ignoring the congregation.","summary_fr":"L’orientation liturgique commune concerne la direction du culte, non le fait que le prêtre ignorerait l’assemblée.","body":["In the usual arrangement of the traditional Roman Mass, priest and people are oriented together toward the altar, cross and liturgical east. The action is addressed principally to God; the celebrant leads the Church’s prayer rather than conducting a face-to-face meeting with the congregation.","This must not be turned into a false historical absolute. The 1962 Ritus servandus explicitly gives instructions for an altar that is ad orientem, versus populum: if the celebrant already faces the people, he does not turn away from the altar for Dominus vobiscum, Orate fratres, Ite missa est or the blessing. The rubrics therefore know more than one physical church arrangement.","The best way to understand ad orientem is therefore as common liturgical orientation: the priest’s bodily position serves the sacrificial and Godward structure of the rite. Historical claims about the exact orientation of every ancient Roman church should be treated as scholarship, not as a rubric or dogma."],"body_fr":["Dans la disposition habituelle de la Messe romaine traditionnelle, le prêtre et les fidèles sont orientés ensemble vers l’autel, la croix et l’orient liturgique. L’action s’adresse d’abord à Dieu ; le célébrant conduit la prière de l’Église plutôt qu’une réunion en face-à-face avec l’assemblée.","Il ne faut pas transformer cela en absolu historique simpliste. Le Ritus servandus de 1962 donne explicitement des instructions pour un autel ad orientem, versus populum : si le célébrant fait déjà face au peuple, il ne se retourne pas pour Dominus vobiscum, Orate fratres, Ite missa est ou la bénédiction. Les rubriques connaissent donc plus d’une disposition physique des églises.","Le meilleur cadre est donc celui de l’orientation liturgique commune : la position corporelle du prêtre sert la structure sacrificielle et tournée vers Dieu du rite. Les affirmations sur l’orientation exacte de toutes les églises romaines anciennes relèvent de l’histoire liturgique, non d’une rubrique ou d’un dogme."],"sources":["mr1962","oconnell1964","fortescueMass","jungmann"]},{"id":"latin","title":"Why Latin?","title_fr":"Pourquoi le latin ?","summary":"Latin became the stable liturgical language of the Roman Church; understanding and Latin were never meant to be opposites.","summary_fr":"Le latin est devenu la langue liturgique stable de l’Église romaine ; comprendre la Messe et employer le latin ne sont pas des réalités opposées.","body":["Latin was not the language of the earliest Christian liturgy everywhere, but it became the characteristic liturgical language of the Latin Church and acquired a stable technical and sacred vocabulary. By 1962, the Roman books presuppose Latin for the liturgical texts except where particular permissions applied.","The Council of Trent defended the received liturgical usage while simultaneously insisting that pastors explain what is read and the mysteries of the sacrifice to the faithful. The 1958 instruction likewise envisaged the people answering and singing substantial parts of Mass in Latin while also allowing pastoral explanation and, in defined circumstances, vernacular reading of the Epistle and Gospel.","The point is therefore not that incomprehension is valuable. The traditional system combines a stable liturgical language with catechesis, translations, hand missals, preaching and learned participation."],"body_fr":["Le latin n’a pas été partout la langue des toutes premières liturgies chrétiennes, mais il est devenu la langue liturgique caractéristique de l’Église latine et a acquis un vocabulaire sacré et technique stable. En 1962, les livres romains présupposent le latin pour les textes liturgiques, sauf permissions particulières.","Le Concile de Trente défend l’usage liturgique reçu tout en demandant aux pasteurs d’expliquer aux fidèles ce qui est lu et les mystères du sacrifice. L’instruction de 1958 envisage de même que les fidèles répondent et chantent des parties importantes de la Messe en latin, tout en permettant l’explication pastorale et, dans des cas déterminés, la lecture en langue vernaculaire de l’Épître et de l’Évangile.","L’idée n’est donc pas que l’incompréhension aurait une valeur en elle-même. Le système traditionnel associe une langue liturgique stable à la catéchèse, aux traductions, aux missels des fidèles, à la prédication et à une participation formée."],"sources":["trent22","music1958","mr1962"]},{"id":"silent-canon","title":"Why is the Canon quiet?","title_fr":"Pourquoi le Canon est-il dit à voix basse ?","summary":"The quiet Canon is a prescribed feature of the Roman rite, not an accidental absence of participation.","summary_fr":"Le Canon à voix basse est une caractéristique prescrite du rite romain, non une absence accidentelle de participation.","body":["After the Sanctus the 1962 rite enters the Roman Canon, which the celebrant recites quietly except for the prescribed audible moments. The silence changes the soundscape of the church while the central sacrificial prayer continues at the altar.","Trent explicitly rejected the claim that the Roman practice of pronouncing part of the Canon in a low voice should be condemned. Pius XII later emphasized that genuine participation is not reducible to continuous audible speech: interior union with Christ’s sacrifice is primary.","Historically, the quiet Canon developed over centuries. It is better to say that the Roman tradition came to surround the Canon with liturgical silence than to invent one single symbolic origin for the practice."],"body_fr":["Après le Sanctus, le rite de 1962 entre dans le Canon romain, que le célébrant récite à voix basse sauf aux moments où la rubrique prévoit une voix audible. Le paysage sonore de l’église change tandis que la prière sacrificielle centrale se poursuit à l’autel.","Le Concile de Trente rejette explicitement l’idée qu’il faudrait condamner l’usage romain de prononcer une partie du Canon à voix basse. Pie XII rappelle ensuite que la participation véritable ne se réduit pas à une parole continuellement audible : l’union intérieure au sacrifice du Christ est première.","Historiquement, le Canon silencieux s’est développé au cours des siècles. Il vaut mieux dire que la tradition romaine a progressivement entouré le Canon de silence liturgique plutôt que d’inventer une origine symbolique unique."],"sources":["mr1962","trent22","mediatorDei","jungmann"]},{"id":"chant","title":"Why Gregorian chant?","title_fr":"Pourquoi le chant grégorien ?","summary":"In a sung Mass the chant is itself liturgical action, not background music.","summary_fr":"À la Messe chantée, le chant est lui-même une action liturgique, non une musique de fond.","body":["Pius X called Gregorian chant the chant proper to the Roman Church, and Pius XII described it as a treasured patrimony closely fitted to the sacred text. The 1958 instruction continued to give it priority in Roman liturgical celebrations.","This matters for following a traditional sung Mass. The schola may be singing the Introit, Gradual, Offertory or Communion while the celebrant is already performing another prescribed action. Those concurrent tracks are not a synchronization error: they arise from distinct liturgical roles within one rite.","Ad Orientem therefore treats the choir as an active liturgical actor. What you hear and what the celebrant is doing may legitimately differ at the same moment."],"body_fr":["Pie X appelle le chant grégorien le chant propre de l’Église romaine, et Pie XII le décrit comme un patrimoine précieux intimement adapté au texte sacré. L’instruction de 1958 continue de lui donner la priorité dans les célébrations liturgiques romaines.","Cela est essentiel pour suivre une Messe chantée traditionnelle. La schola peut chanter l’Introït, le Graduel, l’Offertoire ou la Communion alors que le célébrant accomplit déjà une autre action prescrite. Ces lignes simultanées ne sont pas une erreur de synchronisation : elles proviennent de rôles liturgiques distincts au sein d’un même rite.","Ad Orientem traite donc le chœur comme un acteur liturgique réel. Ce que vous entendez et ce que fait le célébrant peuvent légitimement différer au même moment."],"sources":["piusX1903","musicae1955","music1958","fortescue1962"]},{"id":"participation","title":"What does participation mean?","title_fr":"Que signifie participer ?","summary":"Traditional participation includes interior offering, bodily action, responses, prayer and chant; it is not one single required behaviour.","summary_fr":"La participation traditionnelle comprend l’offrande intérieure, les attitudes du corps, les réponses, la prière et le chant ; elle ne se réduit pas à un comportement unique.","body":["Pius XII teaches that the faithful truly participate in the Eucharistic sacrifice while distinguishing their participation from the sacramental action of the ordained priest. Interior union with Christ and with the Church’s offering is fundamental.","The 1958 instruction gives a particularly useful late preconciliar picture: interior participation is primary; it can be completed by posture and gestures, responses, prayers and singing. It even describes increasing degrees of vocal participation at Sung and Low Mass.","This prevents two opposite caricatures. The traditional Mass does not require everyone to remain mute and detached; nor does it require every member of the congregation to say every audible text. Legitimate practice, local custom and the form of Mass all matter."],"body_fr":["Pie XII enseigne que les fidèles participent réellement au sacrifice eucharistique tout en distinguant leur participation de l’action sacramentelle du prêtre ordonné. L’union intérieure au Christ et à l’offrande de l’Église est fondamentale.","L’instruction de 1958 offre une image particulièrement utile de la fin de la période préconciliaire : la participation intérieure est première ; elle peut être complétée par les attitudes et gestes, les réponses, les prières et le chant. Elle décrit même plusieurs degrés de participation vocale à la Messe chantée et à la Messe basse.","Cela évite deux caricatures opposées. La Messe traditionnelle n’exige pas que tous restent muets et détachés ; elle n’exige pas non plus que toute l’assemblée prononce tous les textes audibles. La pratique légitime, la coutume locale et la forme de Messe comptent."],"sources":["mediatorDei","music1958"]},{"id":"concurrency","title":"Why are the priest and choir doing different things?","title_fr":"Pourquoi le prêtre et le chœur font-ils des choses différentes ?","summary":"A Solemn or Sung Mass contains several coordinated liturgical roles that can proceed concurrently.","summary_fr":"Une Messe solennelle ou chantée comporte plusieurs rôles liturgiques coordonnés qui peuvent avancer simultanément.","body":["The Roman Mass is not always a single serial script in which every person waits for the preceding text to finish. The celebrant, sacred ministers and schola have distinct assigned texts and actions. In several places the chant continues while the priest proceeds with quieter prayers at the altar.","This is especially noticeable at the Introit, Gradual, Offertory, Sanctus/Benedictus and Communion. A hand missal that prints everything in one column can hide this structure; a live guide needs to model it explicitly.","The app’s HEAR and complete-action views therefore answer different questions: one follows the audible landmark; the other follows the complete liturgical action."],"body_fr":["La Messe romaine n’est pas toujours un scénario strictement séquentiel dans lequel chacun attend que le texte précédent soit terminé. Le célébrant, les ministres sacrés et la schola ont des textes et des actions propres. À plusieurs endroits, le chant continue tandis que le prêtre poursuit des prières plus silencieuses à l’autel.","Cela est particulièrement visible à l’Introït, au Graduel, à l’Offertoire, au Sanctus/Benedictus et à la Communion. Un missel qui imprime tout en une seule colonne peut masquer cette structure ; un guide en temps réel doit au contraire la représenter explicitement.","Les vues d’écoute et d’action complète de l’application répondent donc à deux questions différentes : l’une suit le repère audible, l’autre l’ensemble de l’action liturgique."],"sources":["mr1962","fortescue1962","music1958"]},{"id":"incense","title":"Why incense?","title_fr":"Pourquoi l’encens ?","summary":"Incense is a liturgical sign of honour and solemnity applied to altar, offerings, ministers and persons according to the rite.","summary_fr":"L’encens est un signe liturgique d’honneur et de solennité appliqué à l’autel, aux offrandes, aux ministres et aux personnes selon le rite.","body":["The 1962 ceremonial prescribes incense at defined moments in Solemn Mass and, where permitted, at sung Mass: the altar at the entrance, the Gospel, and the offerings and altar at the Offertory, followed by the prescribed incensations of persons.","Its meaning should not be reduced to one allegory. Biblical prayer imagery, honour, purification and solemnity all contribute to the Church’s use of incense. The immediate question in the live rite is first rubrical: what is being incensed, by whom, and at which point.","Requiem ceremonial deliberately differs in some incensations, which is why a learning guide must distinguish the form of Mass rather than attach one generic explanation to every use."],"body_fr":["Le cérémonial de 1962 prescrit l’encens à des moments déterminés de la Messe solennelle et, là où cela est permis, de la Messe chantée : l’autel à l’entrée, l’Évangile, puis les offrandes et l’autel à l’Offertoire, suivis des encensements prescrits des personnes.","Sa signification ne doit pas être réduite à une seule allégorie. L’image biblique de la prière, l’honneur, la purification et la solennité contribuent tous à l’usage ecclésial de l’encens. Dans le rite concret, la première question reste rubricale : qu’est-ce qui est encensé, par qui et à quel moment ?","Le cérémonial des Requiem diffère volontairement pour certains encensements ; un guide d’apprentissage doit donc distinguer la forme de Messe plutôt que d’appliquer partout une explication générique."],"sources":["mr1962","oconnell1964","fortescue1962"]},{"id":"bells","title":"Why the bells?","title_fr":"Pourquoi les cloches ?","summary":"The server’s bells mark key moments for the congregation, especially around the Sanctus and elevations.","summary_fr":"Les clochettes du servant signalent des moments clés à l’assemblée, surtout autour du Sanctus et des élévations.","body":["In the traditional Roman Mass the small altar bell is a practical and ceremonial signal. It helps the faithful recognize important moments when much of the priest’s prayer is quiet or when visibility may be limited.","The bell is especially associated with the Sanctus and the elevations after each Consecration. Local custom can affect the exact pattern of rings, so the app should identify the liturgical landmark without pretending that every parish’s ringing pattern is universal law.","Historically, bells became increasingly useful as the Canon was said quietly and the elevations became prominent devotional landmarks."],"body_fr":["Dans la Messe romaine traditionnelle, la clochette d’autel est un signal pratique et cérémoniel. Elle aide les fidèles à reconnaître des moments importants lorsque la prière du prêtre est en grande partie silencieuse ou lorsque la visibilité est limitée.","Elle est surtout associée au Sanctus et aux élévations après chacune des Consécrations. La coutume locale peut modifier le nombre exact de sonneries ; l’application doit donc identifier le repère liturgique sans présenter chaque usage paroissial comme une loi universelle.","Historiquement, les clochettes sont devenues particulièrement utiles à mesure que le Canon était récité à voix basse et que les élévations devenaient des repères dévotionnels majeurs."],"sources":["mr1962","oconnell1964","jungmann"]},{"id":"crosses","title":"Why so many signs and gestures?","title_fr":"Pourquoi tant de signes et de gestes ?","summary":"The gestures are prescribed liturgical actions; later spiritual interpretations should not be confused with their historical origin.","summary_fr":"Les gestes sont des actions liturgiques prescrites ; les interprétations spirituelles ultérieures ne doivent pas être confondues avec leur origine historique.","body":["The Roman ceremonial uses bows, genuflections, signs of the Cross, kisses of the altar, extended or joined hands and changes of position. These gestures give bodily form to reverence, blessing, supplication and the ordered roles of the rite.","The safest method is to distinguish three layers. First: the rubric states what is done. Second: theology explains what the action expresses now. Third: history investigates how and when the gesture developed. A pious allegory may be useful without being the historical reason the gesture originated.","That distinction is why this module labels ceremonial, doctrinal, historical and spiritual sources separately."],"body_fr":["Le cérémonial romain emploie inclinations, génuflexions, signes de croix, baisers de l’autel, mains étendues ou jointes et changements de position. Ces gestes donnent une forme corporelle à la révérence, à la bénédiction, à la supplication et à l’ordre des rôles liturgiques.","La méthode la plus sûre distingue trois niveaux. Premièrement : la rubrique indique ce qui est fait. Deuxièmement : la théologie explique ce que l’action exprime aujourd’hui. Troisièmement : l’histoire recherche comment et quand le geste s’est développé. Une allégorie pieuse peut être utile sans être pour autant la raison historique de l’origine du geste.","C’est pourquoi ce module étiquette séparément les sources cérémonielles, doctrinales, historiques et spirituelles."],"sources":["mr1962","oconnell1964","fortescueMass","jungmann","gihr"]},{"id":"forms","title":"Low, Sung and Solemn Mass: what changes?","title_fr":"Messe basse, chantée et solennelle : qu’est-ce qui change ?","summary":"They celebrate the same Roman Mass, but the ministers, chant, ceremonial and audible structure are not identical.","summary_fr":"Elles célèbrent la même Messe romaine, mais les ministres, le chant, le cérémonial et la structure audible ne sont pas identiques.","body":["Low Mass is celebrated without the liturgical chant structure of a Sung Mass. A Missa cantata adds sung celebrant texts and the choir’s Proper and Ordinary, normally without deacon and subdeacon. Solemn Mass adds the sacred ministers and the fuller ceremonial assigned to them.","The 1958 instruction calls Solemn Mass the more noble form because ceremonies, ministers and sacred music combine to express the mysteries more fully. It nevertheless gives Sung Mass and Low Mass their own legitimate structures and forms of participation.","The difference is therefore not simply volume. It changes who proclaims certain texts, processions, incense, the Gospel ceremonial, concurrent chant and the way a congregation experiences the rite."],"body_fr":["La Messe basse est célébrée sans la structure chantée propre à la Messe chantée. La Missa cantata ajoute les textes chantés du célébrant ainsi que le Propre et l’Ordinaire du chœur, normalement sans diacre ni sous-diacre. La Messe solennelle ajoute les ministres sacrés et le cérémonial plus complet qui leur est attribué.","L’instruction de 1958 appelle la Messe solennelle la forme la plus noble parce que cérémonies, ministres et musique sacrée s’unissent pour exprimer plus pleinement les mystères. Elle reconnaît néanmoins à la Messe chantée et à la Messe basse leur structure légitime et leurs formes propres de participation.","La différence n’est donc pas seulement une question de volume sonore. Elle change qui proclame certains textes, les processions, l’encens, le cérémonial de l’Évangile, le chant simultané et l’expérience du rite par l’assemblée."],"sources":["music1958","fortescue1962","oconnell1964"]},{"id":"proper-ordinary","title":"Why do some texts change and others stay the same?","title_fr":"Pourquoi certains textes changent-ils et d’autres restent-ils les mêmes ?","summary":"The Ordinary provides the stable framework; the Proper expresses the specific day, season or saint.","summary_fr":"L’Ordinaire fournit la structure stable ; le Propre exprime le jour, le temps liturgique ou le saint célébré.","body":["The Roman Mass combines a stable Ordinary with variable Propers. The Kyrie, Gloria when prescribed, Creed when prescribed, Sanctus and Agnus belong to the recurring Ordinary; the Introit, Collect, readings, Gradual or Tract, Offertory, Secret, Communion and Postcommunion depend on the celebration.","The calendar and rubrics decide which formulary is actually in force, including commemorations and exceptional days. That is why the app’s calendar/Proper resolver must remain separate from the commentary layer.","Learning the distinction is one of the fastest ways to stop feeling lost: first learn the stable architecture, then let the changing Proper tell you what today’s Mass is about."],"body_fr":["La Messe romaine associe un Ordinaire stable à des Propres variables. Le Kyrie, le Gloria lorsqu’il est prescrit, le Credo lorsqu’il est prescrit, le Sanctus et l’Agnus appartiennent à l’Ordinaire récurrent ; l’Introït, la Collecte, les lectures, le Graduel ou le Trait, l’Offertoire, la Secrète, la Communion et la Postcommunion dépendent de la célébration.","Le calendrier et les rubriques déterminent quel formulaire est effectivement en vigueur, y compris les commémoraisons et les jours exceptionnels. C’est pourquoi le moteur calendrier/Propre de l’application doit rester distinct de la couche de commentaire.","Comprendre cette distinction est l’un des moyens les plus rapides de ne plus se sentir perdu : apprendre d’abord l’architecture stable, puis laisser le Propre variable montrer ce que célèbre la Messe du jour."],"sources":["mr1962","rubricarum1960"]},{"id":"history-not-static","title":"Was the 1962 Mass unchanged since the Apostles?","title_fr":"La Messe de 1962 est-elle restée inchangée depuis les Apôtres ?","summary":"No. It is the product of organic Roman liturgical development, later standardisation and repeated authorized revisions.","summary_fr":"Non. Elle est le fruit du développement organique de la liturgie romaine, puis de sa normalisation et de révisions autorisées successives.","body":["The Roman Mass contains very ancient elements, but its complete 1962 form did not exist unchanged in the apostolic age. The Roman Canon, entrance rites, Offertory prayers, private preparations, elevations, Last Gospel and other features developed at different periods.","The Missal of Pius V in 1570 standardized the Roman books after Trent; it did not invent the Roman Mass. Later popes continued to revise calendar, rubrics and texts. Pius XII reformed Holy Week, and John XXIII promulgated a new Code of Rubrics in 1960 before the 1962 typical Missal.","Serious history therefore avoids two myths at once: that everything was created in 1570, and that every detail of 1962 is unchanged from the first century."],"body_fr":["La Messe romaine contient des éléments très anciens, mais sa forme complète de 1962 n’existait pas inchangée à l’époque apostolique. Le Canon romain, les rites d’entrée, les prières d’Offertoire, les préparations privées, les élévations, le Dernier Évangile et d’autres éléments se sont développés à des périodes différentes.","Le Missel de Pie V en 1570 a normalisé les livres romains après le Concile de Trente ; il n’a pas inventé la Messe romaine. Les papes suivants ont continué à modifier calendrier, rubriques et textes. Pie XII a réformé la Semaine sainte et Jean XXIII a promulgué un nouveau Code des rubriques en 1960 avant l’édition typique de 1962.","Une histoire sérieuse évite donc deux mythes à la fois : que tout aurait été créé en 1570, ou que chaque détail de 1962 serait demeuré inchangé depuis le Ier siècle."],"sources":["fortescueMass","jungmann","rubricarum1960","holyweek1955"]}],"LESSONS":[{"id":"mass","n":1,"title":"What is the Mass?","title_fr":"Qu’est-ce que la Messe ?","summary":"Start with sacrifice, sacramental presence and the distinct roles of priest and faithful.","summary_fr":"Commencer par le sacrifice, la présence sacramentelle et les rôles distincts du prêtre et des fidèles.","body":"The traditional Roman Mass is first understood as the Church’s sacramental offering of the one sacrifice of Christ. Its ceremonies serve that reality; they are not a performance added around it. Learn the difference between the ordained priest’s sacramental action and the real participation of the faithful.","body_fr":"La Messe romaine traditionnelle se comprend d’abord comme l’offrande sacramentelle par l’Église de l’unique sacrifice du Christ. Ses cérémonies servent cette réalité ; elles ne sont pas un spectacle ajouté autour d’elle. Il faut distinguer l’action sacramentelle du prêtre ordonné de la participation réelle des fidèles.","topics":["participation"],"steps":["offertory","consecration-host","communion-faithful"],"sources":["trent22","mediatorDei","ccc"]},{"id":"read","n":2,"title":"How to read a traditional Mass","title_fr":"Comment lire une Messe traditionnelle","summary":"Learn Ordinary vs Proper, audible vs quiet prayer, and simultaneous liturgical tracks.","summary_fr":"Comprendre Ordinaire et Propre, prière audible et silencieuse, et lignes liturgiques simultanées.","body":"Before memorising details, learn the architecture. Some texts remain stable, some change with the day, and at Sung Mass the priest and schola can legitimately be in different places in the printed missal at the same moment.","body_fr":"Avant de mémoriser les détails, il faut apprendre l’architecture. Certains textes restent stables, d’autres changent avec le jour ; à la Messe chantée, le prêtre et la schola peuvent légitimement se trouver à des endroits différents du missel imprimé au même moment.","topics":["proper-ordinary","concurrency"],"steps":["introit","gospel","offertory","communion-proper"],"sources":["mr1962","music1958"]},{"id":"space","n":3,"title":"Sacred space and orientation","title_fr":"Espace sacré et orientation","summary":"Altar, cross, sanctuary, Epistle/Gospel sides and common liturgical orientation.","summary_fr":"Autel, croix, sanctuaire, côtés de l’Épître et de l’Évangile et orientation liturgique commune.","body":"The sanctuary is organized around the altar and the sacrificial action. Orientation, movement between the altar and the two sides, and the location of ministers make more sense once the church is read as liturgical space rather than as a stage facing an audience.","body_fr":"Le sanctuaire est organisé autour de l’autel et de l’action sacrificielle. L’orientation, les déplacements entre l’autel et ses deux côtés et la place des ministres deviennent plus intelligibles lorsque l’église est lue comme un espace liturgique plutôt que comme une scène tournée vers un public.","topics":["orientation"],"steps":["oramus-te","epistle","gospel"],"sources":["mr1962","fortescue1962"]},{"id":"foot","n":4,"title":"Before approaching the altar","title_fr":"Avant de s’approcher de l’autel","summary":"Introibo, Psalm 42 and the two Confiteors form the immediate preparation at the foot of the altar.","summary_fr":"Introibo, le psaume 42 et les deux Confiteor forment la préparation immédiate au bas de l’autel.","body":"These prayers prepare celebrant and ministers before the priest ascends to the altar. They are important, but historical study shows that they developed as preparatory prayers rather than belonging unchanged to the earliest Roman entrance rite.","body_fr":"Ces prières préparent le célébrant et les ministres avant que le prêtre monte à l’autel. Elles sont importantes, mais l’histoire montre qu’elles se sont développées comme prières préparatoires plutôt qu’elles n’appartiennent inchangées au plus ancien rite d’entrée romain.","topics":["history-not-static"],"steps":["sign-cross","judica","priest-confiteor","ministers-confiteor","ascend"],"sources":["mr1962","fortescueMass","jungmann"]},{"id":"entrance","n":5,"title":"Entrance, Kyrie, Gloria and Collect","title_fr":"Entrée, Kyrie, Gloria et Collecte","summary":"See how entrance chant, supplication, praise and the proper prayer of the day form the opening movement.","summary_fr":"Voir comment chant d’entrée, supplication, louange et prière propre du jour forment le mouvement d’ouverture.","body":"The Introit belongs to the Proper; the Kyrie is the distinctive Greek supplication; the Gloria appears when prescribed; the Collect gathers the prayer of the celebration before the readings.","body_fr":"L’Introït appartient au Propre ; le Kyrie est la supplication grecque caractéristique ; le Gloria apparaît lorsqu’il est prescrit ; la Collecte rassemble la prière de la célébration avant les lectures.","topics":["chant","proper-ordinary"],"steps":["introit","kyrie","gloria","collect"],"sources":["mr1962","piusX1903"]},{"id":"word","n":6,"title":"The readings and Gospel","title_fr":"Les lectures et l’Évangile","summary":"Epistle, interlectional chants, Gospel ceremonial and Creed form the didactic part of the Mass.","summary_fr":"Épître, chants entre les lectures, cérémonial de l’Évangile et Credo forment la partie didactique de la Messe.","body":"At Solemn Mass the ministers visibly differentiate the Epistle and Gospel. The Gospel receives greater ceremonial solemnity with blessing, procession, candles and incense. The Creed follows when the rubrics prescribe it.","body_fr":"À la Messe solennelle, les ministres distinguent visiblement l’Épître et l’Évangile. L’Évangile reçoit une solennité cérémonielle plus grande avec bénédiction, procession, cierges et encens. Le Credo suit lorsque les rubriques le prescrivent.","topics":["incense"],"steps":["epistle","gradual","gospel-prep","gospel","credo"],"sources":["mr1962","fortescue1962"]},{"id":"offertory","n":7,"title":"The Offertory","title_fr":"L’Offertoire","summary":"Follow the preparation and oblation of bread and wine without confusing it with the Consecration.","summary_fr":"Suivre la préparation et l’oblation du pain et du vin sans la confondre avec la Consécration.","body":"The Offertory moves from the liturgy of readings toward the Eucharistic sacrifice. Bread and wine are prepared and offered with the Roman Offertory prayers; water is mixed with wine; incense and the Lavabo may follow; Orate fratres and the Secret complete the preparation.","body_fr":"L’Offertoire conduit de la liturgie des lectures vers le sacrifice eucharistique. Pain et vin sont préparés et offerts avec les prières romaines de l’Offertoire ; l’eau est mêlée au vin ; l’encens et le Lavabo peuvent suivre ; Orate fratres et la Secrète achèvent la préparation.","topics":["incense","crosses"],"steps":["offertory","offer-host","water-wine","offer-chalice","lavabo","orate-fratres","secret"],"sources":["mr1962","trent22","mediatorDei"]},{"id":"canon","n":8,"title":"Preface and Roman Canon","title_fr":"Préface et Canon romain","summary":"Understand the transition from audible thanksgiving into the quiet fixed Eucharistic Prayer of the Roman rite.","summary_fr":"Comprendre le passage de l’action de grâces audible à la prière eucharistique fixe et silencieuse du rite romain.","body":"The Preface and Sanctus lead into the Roman Canon. Its prayers intercede for Church, living and dead, invoke communion with the saints, ask acceptance of the oblation, recount the institution and continue in thanksgiving and offering after the Consecration.","body_fr":"La Préface et le Sanctus conduisent au Canon romain. Ses prières intercèdent pour l’Église, les vivants et les morts, invoquent la communion des saints, demandent l’acceptation de l’oblation, rapportent l’institution et se poursuivent après la Consécration dans l’action de grâces et l’offrande.","topics":["silent-canon"],"steps":["preface","sanctus","te-igitur","communicantes","quam-oblationem"],"sources":["mr1962","trent22","mediatorDei"]},{"id":"consecration","n":9,"title":"Consecration and elevations","title_fr":"Consécration et élévations","summary":"The words of Christ effect the sacramental change; genuflections and elevations express adoration.","summary_fr":"Les paroles du Christ accomplissent le changement sacramentel ; génuflexions et élévations expriment l’adoration.","body":"The Consecration is not merely a dramatic remembrance. Catholic doctrine confesses the true sacramental presence of Christ under the species of bread and wine, and the Mass makes sacramentally present the one sacrifice of Calvary rather than repeating it as a new sacrifice.","body_fr":"La Consécration n’est pas seulement un souvenir dramatique. La doctrine catholique confesse la présence sacramentelle véritable du Christ sous les espèces du pain et du vin ; la Messe rend sacramentellement présent l’unique sacrifice du Calvaire au lieu de le répéter comme un nouveau sacrifice.","topics":["bells","crosses"],"steps":["consecration-host","consecration-chalice","unde-et-memores"],"sources":["trent22","mediatorDei","ccc","mr1962"]},{"id":"communion","n":10,"title":"From the Pater to Communion","title_fr":"Du Pater à la Communion","summary":"Lord’s Prayer, fraction, commingling, Agnus Dei and private preparation lead to sacramental Communion.","summary_fr":"Pater, fraction, commixtion, Agnus Dei et préparation privée conduisent à la Communion sacramentelle.","body":"After the Canon, the rite turns toward Communion. The Pater is followed by its embolism, fraction and commingling, Agnus Dei and prayers before Communion. The celebrant receives, and Communion is then distributed to the faithful when appropriate.","body_fr":"Après le Canon, le rite s’oriente vers la Communion. Le Pater est suivi de son embolisme, de la fraction et de la commixtion, de l’Agnus Dei et des prières avant la Communion. Le célébrant communie, puis la Communion est distribuée aux fidèles le cas échéant.","topics":["participation"],"steps":["pater","fraction-pax","commingling","agnus","priest-communion","ecce","communion-faithful"],"sources":["mr1962","ccc"]},{"id":"end","n":11,"title":"Thanksgiving and conclusion","title_fr":"Action de grâces et conclusion","summary":"Ablutions, Communion Proper, Postcommunion, dismissal, blessing and Last Gospel complete the rite.","summary_fr":"Ablutions, Propre de Communion, Postcommunion, renvoi, bénédiction et Dernier Évangile achèvent le rite.","body":"The conclusion is not one sudden ending. The sacred vessels are purified; the Communion antiphon and Postcommunion belong to the day’s Proper; the dismissal and blessing follow their rubrics; the Last Gospel normally closes the 1962 Mass.","body_fr":"La conclusion n’est pas une fin brusque. Les vases sacrés sont purifiés ; l’antienne de Communion et la Postcommunion appartiennent au Propre du jour ; le renvoi et la bénédiction suivent leurs rubriques ; le Dernier Évangile clôt normalement la Messe de 1962.","topics":["history-not-static"],"steps":["ablutions","communion-proper","postcommunion","dismissal","blessing","last-gospel"],"sources":["mr1962","fortescueMass"]},{"id":"forms","n":12,"title":"Low, Sung and Solemn Mass","title_fr":"Messe basse, chantée et solennelle","summary":"Learn how ministers, chant and ceremonial change without changing the identity of the Roman Mass.","summary_fr":"Comprendre comment ministres, chant et cérémonial changent sans changer l’identité de la Messe romaine.","body":"Once the basic order is familiar, compare forms. This explains why a High Mass can look and sound far more complex than a Low Mass even though both celebrate the same Ordinary and Proper structure.","body_fr":"Une fois l’ordre fondamental acquis, comparer les formes. Cela explique pourquoi une Messe chantée peut paraître et sonner beaucoup plus complexe qu’une Messe basse tout en célébrant la même structure d’Ordinaire et de Propre.","topics":["forms","chant","concurrency"],"steps":[],"sources":["music1958","fortescue1962"]},{"id":"year","n":13,"title":"The Proper and the liturgical year","title_fr":"Le Propre et l’année liturgique","summary":"Seasons, saints, colours and formularies explain why the same framework carries different texts every day.","summary_fr":"Temps liturgiques, saints, couleurs et formulaires expliquent pourquoi la même structure porte des textes différents selon les jours.","body":"The calendar determines the celebration and the Proper texts. Sundays, ferias, saints, vigils, Ember Days and exceptional rites can alter texts or structure. The Ordinary gives stability; the Proper supplies today’s theological accent.","body_fr":"Le calendrier détermine la célébration et les textes du Propre. Dimanches, féries, saints, vigiles, Quatre-Temps et rites exceptionnels peuvent modifier les textes ou la structure. L’Ordinaire donne la stabilité ; le Propre fournit l’accent théologique du jour.","topics":["proper-ordinary"],"steps":[],"sources":["rubricarum1960","mr1962"]},{"id":"exceptional","n":14,"title":"Exceptional days and Holy Week","title_fr":"Jours exceptionnels et Semaine sainte","summary":"Candlemas, Ash Wednesday, Palm Sunday and the Triduum do not simply run the normal Sunday template.","summary_fr":"Chandeleur, Mercredi des Cendres, Rameaux et Triduum ne suivent pas simplement le modèle d’un dimanche ordinaire.","body":"The 1950s restoration of Holy Week means older manuals can contain obsolete ceremonial even when their theology remains useful. For Palm Sunday, Holy Thursday, Good Friday and the Easter Vigil, this module treats the restored books and 1962 usage as controlling and labels older history separately.","body_fr":"La restauration de la Semaine sainte dans les années 1950 signifie que les anciens manuels peuvent contenir un cérémonial devenu obsolète même si leur théologie reste utile. Pour les Rameaux, le Jeudi saint, le Vendredi saint et la Vigile pascale, ce module donne autorité aux livres restaurés et à l’usage de 1962, en séparant clairement l’histoire antérieure.","topics":["history-not-static"],"steps":["candlemas-blessing","ashes-antiphon","palms-blessing","gf-prostration","vigil-fire"],"sources":["holyweek1955","mr1962"]}],"TIMELINE":[["c. 2nd–4th centuries","env. IIe–IVe siècles","Early Christian Eucharistic worship is already recognisably structured around readings, prayer, thanksgiving and Communion, while local forms remain diverse.","Le culte eucharistique chrétien ancien est déjà structuré autour des lectures, de la prière, de l’action de grâces et de la Communion, tandis que les formes locales restent diverses.",["jungmann"]],["Late antiquity","Antiquité tardive","The Roman Eucharistic tradition develops a stable core; the Roman Canon becomes one of its defining features.","La tradition eucharistique romaine développe un noyau stable ; le Canon romain devient l’un de ses traits caractéristiques.",["jungmann","fortescueMass"]],["8th–13th centuries","VIIIe–XIIIe siècles","Roman and Frankish usages interact; many preparatory and private priestly prayers, offertory developments and ceremonial layers take shape over time.","Les usages romains et francs interagissent ; de nombreuses prières préparatoires et privées du prêtre, développements de l’Offertoire et couches cérémonielles prennent progressivement forme.",["jungmann","fortescueMass"]],["1570","1570","After Trent, Pius V promulgates a standardized Roman Missal. This consolidates an already existing Roman tradition; it does not create the Mass from nothing.","Après Trente, Pie V promulgue un Missel romain normalisé. Il consolide une tradition romaine déjà existante ; il ne crée pas la Messe à partir de rien.",["trent22","fortescueMass"]],["1903–1914","1903–1914","Pius X promotes Gregorian chant and reforms aspects of Roman liturgical discipline, showing that the inherited rite continues to receive authorized development.","Pie X promeut le chant grégorien et réforme certains aspects de la discipline liturgique romaine, montrant que le rite reçu continue de connaître un développement autorisé.",["piusX1903"]],["1951–1955","1951–1955","Pius XII restores the Easter Vigil and then the full Holy Week order. These changes are essential when reading older ceremonial manuals.","Pie XII restaure la Vigile pascale puis l’ensemble de l’ordre de la Semaine sainte. Ces changements sont essentiels lorsqu’on lit des manuels cérémoniels plus anciens.",["holyweek1955"]],["1958","1958","The Sacred Congregation of Rites issues detailed instructions on sacred music and participation, describing late preconciliar practice for sung and low Mass.","La Sacrée Congrégation des Rites publie des normes détaillées sur la musique sacrée et la participation, décrivant la pratique de la fin de la période préconciliaire pour les Messes chantées et basses.",["music1958"]],["1960","1960","John XXIII promulgates a revised Code of Rubrics, explicitly acknowledging the accumulated history of rubrical additions and revisions.","Jean XXIII promulgue un Code révisé des rubriques, reconnaissant explicitement l’histoire accumulée des ajouts et révisions rubricales.",["rubricarum1960"]],["1962","1962","The typical Roman Missal used by this app is published under John XXIII; St Joseph is inserted into the Communicantes later that year.","L’édition typique du Missel romain utilisée par cette application est publiée sous Jean XXIII ; saint Joseph est inséré dans le Communicantes plus tard la même année.",["mr1962","novis1962"]]],"ROLES":[["celebrant","Celebrant","Célébrant","The priest who offers the Mass sacramentally. His prayers, positions and gestures form the central altar track of the rite.","Le prêtre qui offre sacramentellement la Messe. Ses prières, positions et gestes forment la ligne centrale de l’action à l’autel."],["deacon","Deacon","Diacre","At Solemn Mass he has proper functions including the Gospel, assistance at the altar and specified proclamations and incensations.","À la Messe solennelle il possède des fonctions propres, notamment l’Évangile, l’assistance à l’autel ainsi que certaines proclamations et encensements."],["subdeacon","Subdeacon","Sous-diacre","At Solemn Mass he chants the Epistle and carries out assigned ministerial and altar functions.","À la Messe solennelle il chante l’Épître et accomplit les fonctions ministérielles et d’autel qui lui sont attribuées."],["server","Server / acolytes","Servant / acolytes","They answer the celebrant, assist with books, cruets, bells, candles and other actions according to the form of Mass.","Ils répondent au célébrant et assistent avec les livres, burettes, clochettes, cierges et autres actions selon la forme de Messe."],["thurifer","Thurifer","Thuriféraire","Carries and prepares the thurible and assists with the prescribed incensations.","Porte et prépare l’encensoir et assiste aux encensements prescrits."],["schola","Schola / choir","Schola / chœur","Sings the chants assigned to the choir. At Sung Mass this is a distinct liturgical track that can continue while the celebrant prays at the altar.","Chante les pièces attribuées au chœur. À la Messe chantée, il s’agit d’une ligne liturgique distincte qui peut continuer pendant que le célébrant prie à l’autel."],["faithful","Faithful","Fidèles","Participate interiorly in the sacrifice and, according to the form of Mass and legitimate practice, by posture, responses, prayer and chant.","Participent intérieurement au sacrifice et, selon la forme de Messe et la pratique légitime, par les attitudes, les réponses, la prière et le chant."],["mc","Master of ceremonies","Maître des cérémonies","Coordinates the ministers and ceremonial at more solemn celebrations; his role is practical and rubrical rather than a separate liturgical voice.","Coordonne les ministres et le cérémonial dans les célébrations plus solennelles ; son rôle est pratique et rubrical plutôt qu’une voix liturgique distincte."]],"FORMS":[["Low Mass","Messe basse","No sung liturgical structure; the priest and server carry the audible dialogue. The faithful may participate according to legitimate local practice and the 1958 degrees of participation.","Pas de structure liturgique chantée ; le prêtre et le servant portent le dialogue audible. Les fidèles peuvent participer selon la pratique locale légitime et les degrés décrits en 1958."],["Sung Mass / Missa cantata","Messe chantée / Missa cantata","The celebrant sings the appointed parts and the schola sings the Ordinary and Proper; the full deacon/subdeacon structure of Solemn Mass is normally absent.","Le célébrant chante les parties prescrites et la schola chante l’Ordinaire et le Propre ; la structure complète avec diacre et sous-diacre de la Messe solennelle est normalement absente."],["Solemn Mass","Messe solennelle","The fullest normal ceremonial form, with deacon and subdeacon, chant and the ministerial actions assigned to them.","La forme cérémonielle normale la plus complète, avec diacre et sous-diacre, chant et actions ministérielles qui leur sont attribuées."],["Requiem","Requiem","A Mass for the dead with its own Proper and important ceremonial differences: omissions and altered texts or incensations must be learned as real variants, not treated as errors.","Messe des défunts avec son Propre et d’importantes différences cérémonielles : omissions et modifications de textes ou d’encensements sont de véritables variantes, non des erreurs."]]};
const $=(sel,root=document)=>root.querySelector(sel);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const state={view:'course',detail:null,lang:'en',orderOpen:'foot'};
const progressKey='ao_understand_mass_progress_v1';
const readProgress=()=>{try{return new Set(JSON.parse(localStorage.getItem(progressKey)||'[]'))}catch{return new Set()}};
const writeProgress=set=>{try{localStorage.setItem(progressKey,JSON.stringify([...set]))}catch{}};
function appLang(){return $('.homeScreen')?.dataset.homeLanguage || $('.liveScreen')?.dataset.language || state.lang || 'en'}
function t(en,fr){return state.lang==='fr'?(fr||en):en}
function allSources(){return {...(window.AO_LEARN_SOURCES||{}),...DATA.EXTRA_SOURCES}}
function sourceCard(id){const s=allSources()[id]; if(!s)return''; const fr=state.lang==='fr',label=fr?(s.label_fr||s.label):s.label,kind=fr?(s.kind_fr||s.kind):s.kind,note=fr?(s.note_fr||s.note):s.note;return `<article class="aoSourceCard"><span class="kind">${esc(kind||'Source')}</span><b>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:esc(label)}</b>${note?`<p>${esc(note)}</p>`:''}</article>`}
function sources(ids){const u=[...new Set((ids||[]).filter(Boolean))];return u.length?`<div class="aoSourceListLearn">${u.map(sourceCard).join('')}</div>`:`<div class="aoLearnEmpty">${t('No additional source record is attached here.','Aucune source supplémentaire n’est attachée ici.')}</div>`}
function stepTitle(id){for(const sec of DATA.ORDER){for(const st of sec.steps){if(st[0]===id)return state.lang==='fr'?st[2]:st[1]}}return id}
function topic(id){return DATA.TOPICS.find(x=>x.id===id)}
function lesson(id){return DATA.LESSONS.find(x=>x.id===id)}
function shell(){let r=$('#ao-learn-root'); if(r)return r;r=document.createElement('div');r.id='ao-learn-root';r.className='aoLearnShell';r.hidden=true;document.body.appendChild(r);return r}
function openLearn(){state.lang=appLang();state.view='course';state.detail=null;document.body.classList.add('aoLearnOpen');const r=shell();r.hidden=false;render()}
function closeLearn(){const r=shell();r.hidden=true;document.body.classList.remove('aoLearnOpen')}
function top(){const detail=!!state.detail;return `<header class="aoLearnTop"><button data-learn-${detail?'back':'close'} aria-label="${esc(t(detail?'Back':'Close',detail?'Retour':'Fermer'))}">${detail?'←':'×'}</button><div class="aoLearnTopTitle"><small>${esc(t('Ad Orientem · formation','Ad Orientem · formation'))}</small><b>${esc(t('Understand the Mass','Comprendre la Messe'))}</b></div><button type="button" class="aoModuleHome" data-app-home aria-label="${esc(t('Return to Home','Retour à l’accueil'))}">⌂</button><div class="aoLearnLang"><button data-learn-lang="en" class="${state.lang==='en'?'active':''}">EN</button><button data-learn-lang="fr" class="${state.lang==='fr'?'active':''}">FR</button></div></header>`}
const tabs=[['course','Guided course','Parcours'],['order','Order of Mass','Ordre de la Messe'],['questions','Why?','Pourquoi ?'],['history','History','Histoire'],['roles','Roles & forms','Rôles et formes'],['sources','Sources','Sources']];
function nav(){return `<nav class="aoLearnNav">${tabs.map(([id,en,fr])=>`<button data-learn-view="${id}" class="${state.view===id?'active':''}">${esc(t(en,fr))}</button>`).join('')}</nav>`}
function overview(){return `<section class="aoLearnHero"><div class="aoLearnKicker">${esc(t('Learn away from Mass','Apprendre en dehors de la Messe'))}</div><h1>${esc(t('Understand the Roman Mass','Comprendre la Messe romaine'))}</h1><p>${esc(t('Use this module before or after Mass. During Mass the live guide now keeps explanations deliberately short so attention stays on the liturgy.','Utilisez ce module avant ou après la Messe. Pendant la Messe, le guide en direct garde désormais les explications volontairement brèves afin de préserver l’attention à la liturgie.'))}</p></section><button class="aoUseGuideCard" type="button" data-open-ao-use-guide><span><b>${esc(t('How to use Ad Orientem during Mass','Comment utiliser Ad Orientem pendant la Messe'))}</b><small>${esc(t('Follow modes, HEAR / LOOK / PRIEST / YOU cues, concurrent actions, customs, and when to use commentary.','Modes de suivi, repères HEAR / LOOK / PRIEST / YOU, actions simultanées, coutumes et moment d’utiliser les commentaires.'))}</small></span><span>→</span></button>`}
function renderCourse(){const done=readProgress();return `${overview()}${nav()}<div class="aoLearnSectionHead"><h2>${esc(t('Guided course','Parcours guidé'))}</h2><p>${esc(t('Fourteen lessons from first principles to exceptional rites.','Quatorze leçons, des fondements aux rites exceptionnels.'))}</p></div><div class="aoLessonList">${DATA.LESSONS.map(x=>`<button class="aoLessonCard" data-learn-lesson="${x.id}"><span class="aoLessonNum">${x.n}</span><span><b>${esc(t(x.title,x.title_fr))}</b><small>${esc(t(x.summary,x.summary_fr))}</small></span><span class="aoLessonDone">${done.has(x.id)?'✓':'›'}</span></button>`).join('')}</div><section class="aoManagePanel"><strong>${esc(t('Course progress','Progression du parcours'))}</strong><small>${esc(t('Reset only the 14-lesson completion record. Course content is not changed.','Réinitialise uniquement la progression des 14 leçons. Le contenu du parcours n’est pas modifié.'))}</small><div class="aoManageActions"><button class="danger" data-learn-reset>${esc(t('Reset course progress','Réinitialiser la progression'))}</button></div></section>`}
function renderOrder(){return `${overview()}${nav()}<div class="aoLearnSectionHead"><h2>${esc(t('Explore the Order','Explorer l’Ordre'))}</h2><p>${esc(t('Tap any part for what happens, meaning, history and its source trail.','Touchez une partie pour voir l’action, le sens, l’histoire et les sources.'))}</p></div><div class="aoOrderList">${DATA.ORDER.map((sec,si)=>`<section class="aoOrderSection"><button data-order-toggle="${sec.id}"><b>${esc(t(sec.en,sec.fr))}</b><span>${state.orderOpen===sec.id?'−':'+'}</span></button><div class="aoOrderSteps" ${state.orderOpen===sec.id?'':'hidden'}>${sec.steps.map((st,i)=>`<button class="aoOrderStep" data-learn-step="${st[0]}"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(state.lang==='fr'?st[2]:st[1])}</b><span>›</span></button>`).join('')}</div></section>`).join('')}</div>`}
function renderQuestions(){return `${overview()}${nav()}<div class="aoLearnSectionHead"><h2>${esc(t('Why is it done this way?','Pourquoi fait-on ainsi ?'))}</h2><p>${esc(t('Thematic explanations kept separate from the live Mass.','Explications thématiques séparées de la Messe en direct.'))}</p></div><div class="aoTopicGrid">${DATA.TOPICS.map(x=>`<button class="aoTopicCard" data-learn-topic="${x.id}"><b>${esc(t(x.title,x.title_fr))}</b><p>${esc(t(x.summary,x.summary_fr))}</p></button>`).join('')}</div>`}
function renderHistory(){return `${overview()}${nav()}<div class="aoLearnSectionHead"><h2>${esc(t('A short history of the Roman Mass','Brève histoire de la Messe romaine'))}</h2><p>${esc(t('Development without the myths of “invented in 1570” or “unchanged since the Apostles.”','Un développement historique sans les mythes « inventée en 1570 » ou « inchangée depuis les Apôtres ».'))}</p></div><div class="aoTimeline">${DATA.TIMELINE.map(x=>`<article class="aoTimelineItem"><b>${esc(state.lang==='fr'?x[1]:x[0])}</b><p>${esc(state.lang==='fr'?x[3]:x[2])}</p><div class="aoLinkChips">${x[4].map(id=>{const q=allSources()[id]||{};const lab=state.lang==='fr'?(q.label_fr||q.label):q.label;return `<button data-learn-source="${id}">${esc((lab||id).split(' · ')[0])}</button>`}).join('')}</div></article>`).join('')}</div>`}
function renderRoles(){return `${overview()}${nav()}<div class="aoLearnSectionHead"><h2>${esc(t('Who does what?','Qui fait quoi ?'))}</h2><p>${esc(t('The Mass is a coordinated action of distinct liturgical roles.','La Messe est une action coordonnée de rôles liturgiques distincts.'))}</p></div><div class="aoRoleGrid">${DATA.ROLES.map(x=>`<article class="aoRoleCard"><b>${esc(state.lang==='fr'?x[2]:x[1])}</b><p>${esc(state.lang==='fr'?x[4]:x[3])}</p></article>`).join('')}</div><div class="aoLearnSectionHead"><h2>${esc(t('Forms of Mass','Formes de Messe'))}</h2></div><div class="aoFormsGrid">${DATA.FORMS.map(x=>`<article class="aoFormCard"><b>${esc(state.lang==='fr'?x[1]:x[0])}</b><p>${esc(state.lang==='fr'?x[3]:x[2])}</p></article>`).join('')}</div><div class="aoLinkChips"><button data-learn-topic="forms">${esc(t('Go deeper: Low, Sung and Solemn Mass','Approfondir : Messe basse, chantée et solennelle'))}</button><button data-learn-topic="concurrency">${esc(t('Why concurrent actions?','Pourquoi des actions simultanées ?'))}</button></div>`}
function renderSources(){const src=allSources();return `${overview()}${nav()}<div class="aoLearnSectionHead"><h2>${esc(t('Sources and authority','Sources et autorité'))}</h2><p>${esc(t('Not every source answers the same kind of question.','Toutes les sources ne répondent pas au même type de question.'))}</p></div><div class="aoAuthority"><div><b>${esc(t('1 · Liturgical books and decrees','1 · Livres liturgiques et décrets'))}</b><span>${esc(t('Control what is done in the 1962 rite.','Déterminent ce qui est fait dans le rite de 1962.'))}</span></div><div><b>${esc(t('2 · Magisterial doctrine','2 · Doctrine magistérielle'))}</b><span>${esc(t('Explains sacrifice, participation, Eucharistic theology and principles.','Explique le sacrifice, la participation, la théologie eucharistique et les principes.'))}</span></div><div><b>${esc(t('3 · Contemporary ceremonial manuals','3 · Manuels cérémoniels contemporains'))}</b><span>${esc(t('Explain practical execution close to the 1962 books.','Expliquent l’exécution pratique au plus près des livres de 1962.'))}</span></div><div><b>${esc(t('4 · Historical scholarship','4 · Recherche historique'))}</b><span>${esc(t('Investigates how the rite developed; it does not override the rubrics.','Étudie le développement du rite ; elle ne remplace pas les rubriques.'))}</span></div><div><b>${esc(t('5 · Spiritual interpretation','5 · Interprétation spirituelle'))}</b><span>${esc(t('May illuminate meaning but is labelled as interpretation, not historical origin.','Peut éclairer le sens mais reste étiquetée comme interprétation, non comme origine historique.'))}</span></div></div><div class="aoSourceListLearn">${Object.keys(src).map(sourceCard).join('')}</div>`}
function lessonPager(x){const i=DATA.LESSONS.findIndex(v=>v.id===x.id);return `<nav class="aoLessonPager"><button data-learn-prev ${i<=0?'disabled':''}>← ${esc(t('Previous lesson','Leçon précédente'))}</button><button data-learn-next ${i<0||i>=DATA.LESSONS.length-1?'disabled':''}>${esc(t('Next lesson','Leçon suivante'))} →</button></nav>`}
function renderLesson(x){const done=readProgress().has(x.id);return `<div class="aoArticleHead"><div class="aoLearnKicker">${esc(t('Lesson','Leçon'))} ${x.n} / ${DATA.LESSONS.length}</div><h1>${esc(t(x.title,x.title_fr))}</h1><p>${esc(t(x.summary,x.summary_fr))}</p></div><div class="aoArticleBody"><p>${esc(t(x.body,x.body_fr))}</p>${x.topics?.length?`<h2>${esc(t('Go deeper','Approfondir'))}</h2><div class="aoLinkChips">${x.topics.map(id=>{const q=topic(id);return q?`<button data-learn-topic="${id}">${esc(t(q.title,q.title_fr))}</button>`:''}).join('')}</div>`:''}${x.steps?.length?`<h2>${esc(t('Explore these parts of Mass','Explorer ces parties de la Messe'))}</h2><div class="aoLinkChips">${x.steps.map(id=>`<button data-learn-step="${id}">${esc(stepTitle(id))}</button>`).join('')}</div>`:''}<h2>${esc(t('Sources','Sources'))}</h2>${sources(x.sources)}<button class="aoMarkDone" data-lesson-done="${x.id}">${esc(done?t('Completed ✓','Terminée ✓'):t('Mark lesson complete','Marquer la leçon comme terminée'))}</button>${lessonPager(x)}</div>`}
function renderTopic(x){return `<div class="aoArticleHead"><div class="aoLearnKicker">${esc(t('Why?','Pourquoi ?'))}</div><h1>${esc(t(x.title,x.title_fr))}</h1><p>${esc(t(x.summary,x.summary_fr))}</p></div><article class="aoArticleBody">${(state.lang==='fr'?x.body_fr:x.body).map(p=>`<p>${esc(p)}</p>`).join('')}<h2>${esc(t('Sources','Sources'))}</h2>${sources(x.sources)}</article>`}
function renderStep(id){
 const e=(window.AO_LEARN_ENRICHMENT||{})[id]||{},f=globalThis.AO_FORMATION_NOTES_V4314?.[id]||{},fr=state.lang==='fr';
 const what=fr?(e.what_fr||e.what):(e.what||''),meaning=fr?(e.meaning_fr||e.meaning):(e.meaning||''),history=fr?(e.history_fr||e.history):(e.history||'');
 const spiritual=fr?(f.spiritual_fr||f.spiritual_en||''):(f.spiritual_en||''),participation=fr?(f.participation_fr||f.participation_en||''):(f.participation_en||''),variation=fr?(f.variation_fr||f.variation_en||''):(f.variation_en||'');
 const g=globalThis.AO_MASS_GUIDANCE_V4313?.resolveGuidance?.(id)||null, srcIds=[...new Set([...(e.sources?.length?e.sources:['mr1962','oconnell1964']),...(f.sources||[])])];
 const authorityLabel=a=>globalThis.AO_MASS_GUIDANCE_V4313?.data?.authority_labels?.[a]?.[state.lang]||a;
 const actionLabel=a=>{const m={SIGN_OF_CROSS:['Sign of the Cross','Signe de croix'],GOSPEL_CROSSES_3:['Three small Gospel crosses','Trois petites croix de l’Évangile'],BREAST_STRIKE_1:['Strike breast ×1','Frapper la poitrine ×1'],BREAST_STRIKE_3:['Strike breast ×3','Frapper la poitrine ×3'],HEAD_BOW:['Bow the head','Incliner la tête'],PROFOUND_BOW:['Profound bow','Inclination profonde'],GENUFLECT:['Genuflect','Génuflexion'],KNEEL:['Kneel','À genoux'],RISE:['Rise','Se relever'],STAND:['Stand','Debout'],SIT:['Sit','Assis'],ADORATION:['Adore','Adorer'],FOLLOW_LOCAL_CUSTOM:['Follow local custom','Suivre l’usage local']};return (m[a]||[String(a||'').replaceAll('_',' '),String(a||'').replaceAll('_',' ')])[fr?1:0]};
 const facts=[];if(g?.posture)facts.push(`<div class="aoLearnGuideFact"><b>${esc(t('Posture','Posture'))}</b><span>${esc(actionLabel(g.posture.action))}</span><small>${esc(authorityLabel(g.posture.authority))}</small></div>`);for(const r of (g?.gestures||[]))facts.push(`<div class="aoLearnGuideFact"><b>${esc(t('Gesture','Geste'))}</b><span>${esc(actionLabel(r.action))}${r.anchor_lat?` · <em>${esc(r.anchor_lat)}</em>`:''}</span><small>${esc(authorityLabel(r.authority))}</small></div>`);
 return `<div class="aoArticleHead"><div class="aoLearnKicker">${esc(t('Order of Mass','Ordre de la Messe'))}</div><h1>${esc(stepTitle(id))}</h1></div><div class="aoStepMeta"><section><h3>${esc(t('What happens','Que se passe-t-il ?'))}</h3><p>${esc(what||t('This step belongs to the liturgical action of the Mass.','Cette étape appartient à l’action liturgique de la Messe.'))}</p></section>${facts.length||participation?`<section class="aoLearnGuidance"><h3>${esc(t('What the faithful do','Ce que font les fidèles'))}</h3>${facts.length?`<div class="aoLearnGuideFacts">${facts.join('')}</div>`:''}${participation?`<p>${esc(participation)}</p>`:''}</section>`:''}${variation?`<section><h3>${esc(t('Variations & exceptions','Variantes et exceptions'))}</h3><p>${esc(variation)}</p></section>`:''}${meaning?`<section><h3>${esc(t('What it means','Ce que cela signifie'))}</h3><p>${esc(meaning)}</p></section>`:''}${spiritual?`<section><h3>${esc(t('Spiritual reading','Lecture spirituelle'))}</h3><p>${esc(spiritual)}</p><small class="aoInterpretiveNote">${esc(t('Traditional spiritual interpretation; not a rubric or historical claim.','Interprétation spirituelle traditionnelle ; ni rubrique ni affirmation historique.'))}</small></section>`:''}${history?`<section><h3>${esc(t('Historical context','Contexte historique'))}</h3><p>${esc(history)}</p></section>`:''}<section><h3>${esc(t('Sources','Sources'))}</h3>${sources(srcIds)}</section></div>`}
function renderSource(id){const s=allSources()[id];if(!s)return `<div class="aoLearnEmpty">${esc(id)}</div>`;return `<div class="aoArticleHead"><div class="aoLearnKicker">${esc(t('Source','Source'))}</div><h1>${esc(state.lang==='fr'?(s.label_fr||s.label):s.label)}</h1><p>${esc(state.lang==='fr'?(s.note_fr||s.note):s.note)}</p></div>${sourceCard(id)}`}
function render(){const r=shell();let body='';if(state.detail){if(state.detail.type==='lesson')body=renderLesson(lesson(state.detail.id));else if(state.detail.type==='topic')body=renderTopic(topic(state.detail.id));else if(state.detail.type==='step')body=renderStep(state.detail.id);else if(state.detail.type==='source')body=renderSource(state.detail.id)}else{body=state.view==='course'?renderCourse():state.view==='order'?renderOrder():state.view==='questions'?renderQuestions():state.view==='history'?renderHistory():state.view==='roles'?renderRoles():renderSources()}r.innerHTML=`${top()}<div class="aoLearnWrap">${body}</div>`;r.scrollTop=0;queueMicrotask(()=>globalThis.AO_TRADITIONAL_CATECHISM?.enhanceUnderstand?.())}
function back(){state.detail=null;render()}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.closest('#ao-learn-root')){if(el.matches('[data-learn-close]')){closeLearn();return}if(el.matches('[data-learn-back]')){back();return}if(el.matches('[data-learn-prev],[data-learn-next]')){const i=DATA.LESSONS.findIndex(v=>v.id===state.detail?.id),n=i+(el.matches('[data-learn-prev]')?-1:1);if(n>=0&&n<DATA.LESSONS.length){state.detail={type:'lesson',id:DATA.LESSONS[n].id};render()}return}if(el.matches('[data-learn-reset]')){if(confirm(t('Reset the 14-lesson course progress?','Réinitialiser la progression des 14 leçons ?'))){writeProgress(new Set());render()}return}if(el.dataset.learnLang){state.lang=el.dataset.learnLang;render();return}if(el.dataset.learnView){state.view=el.dataset.learnView;state.detail=null;render();return}if(el.dataset.learnLesson){state.detail={type:'lesson',id:el.dataset.learnLesson};render();return}if(el.dataset.learnTopic){state.detail={type:'topic',id:el.dataset.learnTopic};render();return}if(el.dataset.learnStep){state.detail={type:'step',id:el.dataset.learnStep};render();return}if(el.dataset.learnSource){state.detail={type:'source',id:el.dataset.learnSource};render();return}if(el.dataset.orderToggle){state.orderOpen=state.orderOpen===el.dataset.orderToggle?'':el.dataset.orderToggle;render();return}if(el.dataset.lessonDone){const p=readProgress();p.has(el.dataset.lessonDone)?p.delete(el.dataset.lessonDone):p.add(el.dataset.lessonDone);writeProgress(p);render();return}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!shell().hidden){state.detail?back():closeLearn()}});
window.AO_UNDERSTAND_MASS={open:openLearn,close:closeLearn,back:()=>{if(state.detail){back();return true}closeLearn();return true},openStep:(id)=>{if(!DATA.ORDER.some(g=>g.steps.some(x=>x[0]===id)))return false;state.lang=appLang();state.detail={type:'step',id};document.body.classList.add('aoLearnOpen');const r=shell();r.hidden=false;render();return true},openLesson:(id)=>{const x=DATA.LESSONS.find(v=>v.id===id);if(!x)return false;state.detail={type:'lesson',id};render();return true},nextLesson:(delta=1)=>{if(state.detail?.type!=='lesson')return false;const i=DATA.LESSONS.findIndex(v=>v.id===state.detail.id),n=i+Number(delta);if(n<0||n>=DATA.LESSONS.length)return false;state.detail={type:'lesson',id:DATA.LESSONS[n].id};render();return true},resetProgress:()=>{writeProgress(new Set());render();return true},restoreState:(x={})=>{state.lang=x.lang||appLang();state.view=x.view||'course';state.detail=x.detail||null;document.body.classList.add('aoLearnOpen');const r=shell();r.hidden=false;render();return true},getState:()=>({...state}),lessons:DATA.LESSONS.map(x=>({id:x.id,n:x.n,title:x.title,title_fr:x.title_fr}))};
})();
